action_details.action_postfix:
// Physical nexus established - filing required
true result.mi_has_nexus xdef
"Michigan filing required: Physical presence (office, employees, or property in state)" job.audit_trail swap addto

// Economic nexus established per Wayfair - filing required
true result.mi_has_nexus xdef
"Michigan filing required: Economic nexus (exceeds $100,000 gross receipts threshold)" job.audit_trail swap addto

// Calculate Michigan state additions
0.0 /mi_additions xdef

// Common Michigan additions:
// - Federal bond interest
// - IRC 199A qualified business income deduction addback
// - Bonus depreciation (partial decoupling)

result.mi_us_interest_income 0.0 ne
{
  mi_additions result.mi_us_interest_income add /mi_additions xdef
} if

mi_additions result.mi_state_additions xdef

// Calculate Michigan state subtractions
0.0 /mi_subtractions xdef

// Common Michigan subtractions:
// - Michigan municipal bond interest
// - Michigan NOL deduction

result.mi_municipal_interest 0.0 ne
{
  mi_subtractions result.mi_municipal_interest add /mi_subtractions xdef
} if

mi_subtractions result.mi_state_subtractions xdef

"Michigan additions: $" result.mi_state_additions cvs strconcat ", subtractions: $" strconcat result.mi_state_subtractions cvs strconcat job.audit_trail swap addto

// Calculate Michigan taxable income // Federal taxable income apportioned to MI + additions - subtractions result.mi_apportioned_income result.mi_state_additions add result.mi_state_subtractions sub 0.0 max result.mi_taxable_income xdef
// Calculate Michigan tax using flat rate: 6.0% result.mi_taxable_income result.mi_corp_tax_rate mul /mi_tax_before_credits xdef
// Subtract Michigan state credits mi_tax_before_credits result.mi_state_credits sub 0.0 max result.mi_tax_liability xdef
// Calculate refund or amount owed result.mi_estimated_payments result.mi_tax_liability sub result.mi_refund_or_owed xdef
"Michigan taxable income: $" result.mi_taxable_income cvs strconcat job.audit_trail swap addto "Michigan tax liability (6.0%): $" result.mi_tax_liability cvs strconcat job.audit_trail swap addto
